const N = Math.round(p.puffs), H = api.h, W = api.w;
const src = W * 0.5, base = H - 1;
for (let i = 0; i < N; i++) {
  const ph = (api.t + i / N) % 1;
  const wob = api.rnd(i * 7 + 1) * 2 - 1;
  const y = base - ph * (H - 2);
  const climb = ph;
  const x = src + wob * p.drift * climb + Math.sin(2 * Math.PI * (api.t + i * 0.37)) * p.drift * 0.5 * climb;
  const r = 1 + climb * p.girth * (0.7 + api.rnd(i * 13 + 5) * 0.6);
  const cut = p.fade;
  let a = climb < 0.12 ? climb / 0.12 : 1;
  if (climb > cut) a *= Math.max(0, 1 - (climb - cut) / (1 - cut));
  a *= p.intensity * 0.85;
  if (a <= 0.02) continue;
  const ci = climb < 0.3 ? 6 : climb < 0.55 ? 4 : climb < 0.78 ? 3 : 1;
  api.blob(Math.round(x), Math.round(y), r, ci, a);
  if (climb > 0.45) {
    const shred = 2 + Math.round(climb * 3);
    for (let k = 0; k < shred; k++) {
      const ang = 2 * Math.PI * (api.rnd(i * 31 + k * 3 + 2) + api.t);
      const rr = r * (0.8 + api.rnd(i * 17 + k * 5 + 3) * 1.1);
      const sx = Math.round(x + Math.cos(ang) * rr * 1.3);
      const sy = Math.round(y + Math.sin(ang) * rr * 0.6);
      api.px(sx, sy, k % 2 ? 0 : 1, a * (0.5 - climb * 0.35));
    }
  }
}
for (let k = 0; k < 5; k++) {
  const ph2 = (api.t * 0.7 + k / 5) % 1;
  const yy = Math.round(2 + ph2 * 6);
  const xx = Math.round(src + (api.rnd(k * 11 + 9) * 2 - 1) * p.drift * 1.6);
  api.px(xx, yy, 0, (1 - ph2) * 0.18 * p.intensity);
}
